import{_ as e,a0 as s,w as a,s as u,ao as p,I as r,x as n,a1 as l,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"什麼是容器？為什麼我們關注它？ | LCTT x X-CMD","titleTemplate":false,"description":"什麼是容器？為什麼我們關注它？ | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"什麼是容器？為什麼我們關注它？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"什麼是容器？為什麼我們關注它？ | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20171218 What Are Containers and Why Should You Care-","title":"什麼是容器？為什麼我們關注它？","tag":"201803","desc":""},"relativePath":"201803/20171218 What Are Containers and Why Should You Care-.md","filePath":"[post].md"}'),d={name:"201803/20171218 What Are Containers and Why Should You Care-.md"};function m(f,t,w,x,C,T){const o=s("Link");return a(),u("div",null,[t[25]||(t[25]=p('<h1 id="什麼是容器-為什麼我們關注它" tabindex="-1">什麼是容器？為什麼我們關注它？ <a class="header-anchor" href="#什麼是容器-為什麼我們關注它" aria-label="Permalink to “什麼是容器？為什麼我們關注它？”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/containers-basics.jpg?itok=ZLH9VSaC" alt=""></p><p>什麼是容器？你需要它們嗎？為什麼？在這篇文章中，我們會回答這些基本問題。</p><p>但是，為了回答這些問題，我們要提出更多的問題。當你開始考慮怎麼用容器適配你的工作時，你需要弄清楚：你在哪開發應用？你在哪測試它？你在哪使用它？</p><p>你可能在你的筆記本電腦上開發應用，你的電腦上已經裝好了所需要的庫文件、擴展包、開發工具和開發框架。它在一個模擬生產環境的機器上進行測試，然後被用於生產環境。問題是這三種環境不一定都是一樣的；它們沒有同樣的工具、框架和庫。你在你機器上開發的應用不一定可以在生產環境中正常工作。</p><p>容器解決了這個問題。正如 Docker 解釋的，“容器鏡像是軟件的一個輕量的、獨立的、可執行的包，包括了執行它所需要的所有東西：代碼、運行環境、系統工具、系統庫、設置。”</p><p>這代表着，一旦一個應用被封裝成容器，那麼它所依賴的下層環境就不再重要了。它可以在任何地方運行，甚至在混合雲環境下也可以。這是容器在開發人員，執行團隊，甚至 CIO （信息主管）中變得如此流行的原因之一。</p><h3 id="容器對開發人員的好處" tabindex="-1">容器對開發人員的好處 <a class="header-anchor" href="#容器對開發人員的好處" aria-label="Permalink to “容器對開發人員的好處”">​</a></h3><p>現在開發人員或運維人員不再需要關注他們要使用什麼平台來運行應用。開發人員不會再説：“這在我的系統上運行得好好的。”</p><p>容器的另一個重大優勢是它的隔離性和安全性。因為容器將應用和運行平台隔離開了，應用以及它周邊的東西都會變得安全。同時，不同的團隊可以在一台設備上同時運行不同的應用——對於傳統應用來説這是不可以的。</p>',10)),r("p",null,[t[1]||(t[1]=n("這不是虛擬機（ VM ）所提供的嗎？既是，也不是。虛擬機可以隔離應用，但它負載太高了。",-1)),l(o,{href:"https://www.ubuntu.com/containers"},{default:i(()=>[...t[0]||(t[0]=[n("在一份文獻中",-1)])]),_:1}),t[2]||(t[2]=n("，Canonical 比較了容器和虛擬機，結果是：“容器提供了一種新的虛擬化方法，它有着和傳統虛擬機幾乎相同的資源隔離水平。但容器的負載更小，它佔用更少的內存，更為高效。這意味着可以實現高密度的虛擬化：一旦安裝，你可以在相同的硬件上運行更多應用。”另外，虛擬機啓動前需要更多的準備，而容器只需幾秒就能運行，可以瞬間啓動。",-1))]),t[26]||(t[26]=r("h3",{id:"容器對應用生態的好處",tabindex:"-1"},[n("容器對應用生態的好處 "),r("a",{class:"header-anchor",href:"#容器對應用生態的好處","aria-label":"Permalink to “容器對應用生態的好處”"},"​")],-1)),t[27]||(t[27]=r("p",null,"現在，一個龐大的，由供應商和解決方案組成的生態系統已經可以讓公司大規模地運用容器，不管是用於編排、監控、記錄或者生命週期管理。",-1)),r("p",null,[t[4]||(t[4]=n("為了保證容器可以運行在任何地方，容器生態系統一起成立了",-1)),l(o,{href:"https://www.opencontainers.org/"},{default:i(()=>[...t[3]||(t[3]=[n("開源容器倡議",-1)])]),_:1}),t[5]||(t[5]=n("（OCI）。這是一個 Linux 基金會的項目，目標在於創建關於容器運行環境和容器鏡像格式這兩個容器核心部分的規範。這兩個規範確保容器領域中不會有任何不一致。",-1))]),r("p",null,[t[7]||(t[7]=n("在很長的一段時間裏，容器是專門用於 Linux 內核的，但微軟和 Docker 的密切合作將容器帶到了微軟平台上。現在你可以在 Linux、Windows、Azure、AWS、Google 計算引擎、Rackspace，以及大型計算機上使用容器。甚至 VMware 也正在發展容器，它的 ",-1)),l(o,{href:"https://www.vmware.com/products/vsphere/integrated-containers.html"},{default:i(()=>[...t[6]||(t[6]=[n("vSphere Integrated Container",-1)])]),_:1}),t[8]||(t[8]=n("（VIC）允許 IT 專業人員在他們平台的傳統工作負載上運行容器。",-1))]),t[28]||(t[28]=r("h3",{id:"容器對-cio-的好處",tabindex:"-1"},[n("容器對 CIO 的好處 "),r("a",{class:"header-anchor",href:"#容器對-cio-的好處","aria-label":"Permalink to “容器對 CIO 的好處”"},"​")],-1)),t[29]||(t[29]=r("p",null,"容器在開發人員中因為以上的原因而變得十分流行，同時他們也給 CIO 提供了很大的便利。將工作負載遷移到容器中的優勢正在改變着公司運行的模式。",-1)),t[30]||(t[30]=r("p",null,"傳統的應用有大約十年的生命週期。新版本的發佈需要多年的努力，因為應用是依賴於平台的，有時幾年也不能到達產品階段。由於這個生命週期，開發人員會盡可能在應用裏塞滿各種功能，這會使應用變得龐大笨拙，漏洞百出。",-1)),t[31]||(t[31]=r("p",null,"這個過程影響了公司內部的創新文化。當人們幾個月甚至幾年都不能看到他們的創意被實現時，他們就不再有動力了。",-1)),t[32]||(t[32]=r("p",null,"容器解決了這個問題。因為你可以將應用切分成更小的微服務。你可以在幾周或幾天內開發、測試和部署。新特性可以添加成為新的容器。他們可以在測試結束後以最快的速度被投入生產。公司可以更快轉型，超過他們的競爭者。因為想法可以被很快轉化為容器並部署，這個方式使得創意爆炸式增長。",-1)),t[33]||(t[33]=r("h3",{id:"結論",tabindex:"-1"},[n("結論 "),r("a",{class:"header-anchor",href:"#結論","aria-label":"Permalink to “結論”"},"​")],-1)),t[34]||(t[34]=r("p",null,"容器解決了許多傳統工作負載所面對的問題。但是，它並不能解決所有 IT 專業人員面對的問題。它只是眾多解決方案中的一個。在下一篇文章中，我們將會覆蓋一些容器的基本術語，然後我們會解釋如何開始構建容器。",-1)),r("p",null,[t[10]||(t[10]=n("通過 Linux 基金會和 edX 提供的免費的 ",-1)),l(o,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:i(()=>[...t[9]||(t[9]=[n('"Introduction to Linux" ',-1)])]),_:1}),t[11]||(t[11]=n(" 課程學習更多 Linux 知識。",-1))]),t[35]||(t[35]=r("hr",null,null,-1)),r("p",null,[t[13]||(t[13]=n("via: ",-1)),l(o,{href:"https://www.linux.com/blog/intro-to-Linux/2017/12/what-are-containers-and-why-should-you-care"},{default:i(()=>[...t[12]||(t[12]=[n("https://www.linux.com/blog/intro-to-Linux/2017/12/what-are-containers-and-why-should-you-care",-1)])]),_:1})]),r("p",null,[t[17]||(t[17]=n("作者：",-1)),l(o,{href:"https://www.linux.com/users/arnieswap"},{default:i(()=>[...t[14]||(t[14]=[n("SWAPNIL BHARTIYA",-1)])]),_:1}),t[18]||(t[18]=n(" 譯者：",-1)),l(o,{href:"https://github.com/lonaparte"},{default:i(()=>[...t[15]||(t[15]=[n("lonaparte",-1)])]),_:1}),t[19]||(t[19]=n(" 校對：",-1)),l(o,{href:"https://github.com/wxy"},{default:i(()=>[...t[16]||(t[16]=[n("wxy",-1)])]),_:1})]),r("p",null,[t[22]||(t[22]=n("本文由 ",-1)),l(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[20]||(t[20]=[n("LCTT",-1)])]),_:1}),t[23]||(t[23]=n(" 原創編譯，",-1)),l(o,{href:"https://linux.cn/"},{default:i(()=>[...t[21]||(t[21]=[n("Linux中國",-1)])]),_:1}),t[24]||(t[24]=n(" 榮譽推出",-1))])])}const I=e(d,[["render",m]]);export{b as __pageData,I as default};
